fn remove_duplicates(nums: &Vec<i32>) -> usize {
    if nums.is_empty() {
        return 0; // Return 0 for an empty array
    }

    let mut unique_count = 1; // Start with the first element as unique
    for i in 1..nums.len() {
        if nums[i] != nums[i - 1] {
            unique_count += 1; // Found a new unique value
        }
    }

    unique_count
}